BEGIN;

CREATE TABLE signup (
  name VARCHAR(20) NOT NULL,
  email VARCHAR(45) NOT NULL UNIQUE,
  username VARCHAR(15) PRIMARY KEY,
  dob DATE NOT NULL,
  mobile VARCHAR(10) NOT NULL
);

CREATE TABLE posts (
  post_id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  title VARCHAR(45) NOT NULL UNIQUE,
  content TEXT NOT NULL,
  username VARCHAR(15) NOT NULL REFERENCES signup (username),
  date TIMESTAMP NOT NULL,
  image TEXT
);

CREATE TABLE comments (
  comment_id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  post_id INTEGER NOT NULL,
  username VARCHAR(50) NOT NULL REFERENCES signup (username),
  content TEXT NOT NULL,
  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE likes (
  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  post_id INTEGER NOT NULL,
  username VARCHAR(45) NOT NULL,
  liked SMALLINT CHECK (liked IS NULL OR liked IN (0, 1))
);

CREATE TABLE replies (
  reply_id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  comment_id INTEGER NOT NULL REFERENCES comments (comment_id),
  content TEXT NOT NULL,
  username VARCHAR(45) NOT NULL,
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

-- Converted row data from the MySQL dump follows.





SELECT setval(pg_get_serial_sequence('posts', 'post_id'), COALESCE(MAX(post_id), 1), MAX(post_id) IS NOT NULL) FROM posts;
SELECT setval(pg_get_serial_sequence('comments', 'comment_id'), COALESCE(MAX(comment_id), 1), MAX(comment_id) IS NOT NULL) FROM comments;
SELECT setval(pg_get_serial_sequence('likes', 'id'), COALESCE(MAX(id), 1), MAX(id) IS NOT NULL) FROM likes;
SELECT setval(pg_get_serial_sequence('replies', 'reply_id'), COALESCE(MAX(reply_id), 1), MAX(reply_id) IS NOT NULL) FROM replies;

COMMIT;
